import ChatPage from "@/app/chat/page";
import { PlanChecklist } from "@/components/chat/PlanChecklist";
import { readPlanResponse } from "@/lib/planChecklist";

/* ------------------------------------------------------------ the fixture */

type Ev = { type: string; session_id: string; payload: Record<string, unknown> };
type Body = { run_id: string; steps: { goal: string; state: string }[] };
const FX = JSON.parse(
  readFileSync(path.join(__dirname, "fixtures", "plan-contract-v1350.json"), "utf8").replace(/\r\n/g, "\n"),
) as {
  goals: string[];
  default: { setting: boolean; asks: number; plan: Body };
  allow: { events: Ev[]; plan_awaiting: Body; pending_row: Record<string, unknown>; plan_done: Body };
  declined: Body;
};
const GOALS = FX.goals;
const ASK = FX.allow.events.find((e) => e.type === "approval.requested")!;
const ASK_ID = String(ASK.payload.approval_id);

/** One fixture event as /events frames it (an id, newest-first store). */
function frame(e: Ev) {
  H.ev.n += 1;
  return { id: `e${H.ev.n}`, ts: "", type: e.type, session_id: e.session_id, payload: e.payload };
}
function notify() {
  for (const cb of [...H.ev.listeners]) cb();
}
async function land(...oldestFirst: Ev[]) {
  await act(async () => {
    H.ev.list = [...oldestFirst.map(frame).reverse(), ...H.ev.list];
    notify();
  });
}

/* --------------------------------------------------------------- the page */

const SESSION = "/sessions/s1?transcript=0";
const PLAN = "/sessions/s1/plan";
const PENDING = "/chat/approvals/pending";

function resetApi() {
  H.api.gets.length = 0;
  H.api.posts.length = 0;
  H.api.puts.length = 0;
  for (const k of Object.keys(H.api.getResponses)) delete H.api.getResponses[k];
  Object.assign(H.api.getResponses, {
    "/models": { models: [] },
    "/chat/personas": { personas: [] },
    "/chat/threads": { threads: [] },
    "/settings": { settings: {} },
    "/projects": { projects: [] },
    "/agents/mentionable": { agents: [] },
    "/skills": { skills: [] },
    "/workflows": { workflows: [] },
    "/tools": { tools: [] },
    "/undo?session_id=chat": { actions: [] },
    [SESSION]: { session: { id: "s1", status: "running", summary: "", created_at: "2026-10-17T12:00:00" } },
  });
  H.ev.list = [];
  H.ev.n = 0;
}

/** A saved chat waiting on the helper agent's session "s1". */
function openWaitingChat() {
  H.api.getResponses["/chat/threads/t7"] = {
    id: "t7",
    title: "saved",
    updated_at: "S1",
    messages: [
      { role: "user", content: "file the statements" },
      {
        role: "assistant",
        content: "",
        escalated: "needs the agent",
        escalatedTo: "the builder",
        awaitingSession: "s1",
      },
    ],
  };
  window.history.replaceState({}, "", "/chat?thread=t7");
}

function checklist(root: ParentNode): [string, string][] {
  const list = root.querySelector('[data-testid="plan-checklist"]');
  if (!list) return [];
  return Array.from(list.querySelectorAll('[data-testid="plan-step"]')).map((li) => [
    li.getAttribute("data-state") ?? "",
    li.querySelector('[data-testid="plan-step-goal"]')?.textContent ?? "",
  ]);
}

/** The dock's plan card: its numbered steps, and the buttons it offers. */
async function planCard() {
  const card = await screen.findByTestId("chat-approval-card", {}, { timeout: 10_000 });
  await waitFor(() => expect(within(card).getAllByTestId("approval-plan-step").length).toBe(GOALS.length));
  return card;
}

beforeEach(() => {
  resetApi();
  window.history.replaceState({}, "", "/chat");
  window.localStorage.clear();
  Element.prototype.scrollIntoView = vi.fn();
});
afterEach(() => {
  cleanup();
  vi.clearAllMocks();
});

/* ================================================================ tests */

describe("the daemon's plan shapes, read by the dashboard (the fixture)", () => {
  it("every GET /sessions/{id}/plan body reads as the checklist it says", () => {
    const states = (b: Body) => readPlanResponse(b)!.steps.map((s) => [s.state, s.goal]);
    expect(states(FX.allow.plan_awaiting)).toEqual(GOALS.map((g) => ["waiting", g]));
    expect(states(FX.allow.plan_done)).toEqual(GOALS.map((g) => ["done", g]));
    expect(states(FX.declined)).toEqual(GOALS.map((g) => ["skipped", g]));
    // The shipped default: the setting is OFF, nothing waited, the plan ran.
    expect(FX.default.setting).toBe(false);
    expect(FX.default.asks).toBe(0);
    expect(states(FX.default.plan)).toEqual(GOALS.map((g) => ["done", g]));
    // A declined plan reads "Not attempted" step by step.
    render(<PlanChecklist plan={readPlanResponse(FX.declined)!} />);
    expect(screen.getAllByTestId("plan-step").map((li) => li.textContent)).toEqual(
      GOALS.map((g) => `Not attempted: ${g}`),
    );
    // No plan.proposed: the plan.created + the ask carry the steps.
    expect(FX.allow.events.map((e) => e.type)).not.toContain("plan.proposed");
  });
});

describe("on the chat page: the plan to approve, then the checklist ticking", () => {
  it("the live ask: the plan's steps on the card, Allow once and Deny only; the checklist waits, then ticks", async () => {
    openWaitingChat();
    const [created, requested, ...rest] = FX.allow.events;
    expect([created.type, requested.type]).toEqual(["plan.created", "approval.requested"]);
    H.ev.list = [frame(created), frame(requested)].reverse();
    render(<ChatPage />);
    const row = await screen.findByTestId("agent-run-row");
    await waitFor(() => expect(checklist(row)).toEqual(GOALS.map((g) => ["waiting", g])));
    const card = await planCard();
    expect(within(card).getAllByTestId("approval-plan-step").map((li) => li.textContent)).toEqual(GOALS);
    expect(card.textContent).toContain("The assistant wants to follow this plan");
    expect(within(card).queryByRole("button", { name: "Allow for this chat" })).toBeNull();
    expect(within(card).queryByRole("button", { name: "Always allow exactly this" })).toBeNull();
    expect(within(card).queryByTestId("approval-local-only")).toBeNull();
    expect(within(card).getByRole("button", { name: "Deny" })).toBeTruthy();
    // The plan came with the events: the daemon's copy was not needed.
    expect(H.api.gets).not.toContain(PLAN);
    fireEvent.click(within(card).getByRole("button", { name: "Allow once" }));
    await waitFor(() =>
      expect(H.api.posts).toContainEqual({ path: `/chat/approvals/${ASK_ID}`, body: { decision: "once" } }),
    );
    // The daemon's own events land: the card goes, the steps tick off.
    await land(...rest);
    await waitFor(() => expect(checklist(row)).toEqual(GOALS.map((g) => ["done", g])));
    await waitFor(() => expect(screen.queryByTestId("chat-approval-card")).toBeNull());
  }, 20_000);

  it("a reload while the plan waits: the listing's row and the route's body make the same card", async () => {
    openWaitingChat();
    H.api.getResponses[PLAN] = FX.allow.plan_awaiting;
    H.api.getResponses[PENDING] = { approvals: [FX.allow.pending_row] };
    render(<ChatPage />);
    const row = await screen.findByTestId("agent-run-row");
    await waitFor(() => expect(checklist(row)).toEqual(GOALS.map((g) => ["waiting", g])));
    const card = await planCard();
    // The listing never carries the steps: they come from the plan the page
    // already read, so the card still shows what will be approved.
    expect(FX.allow.pending_row).not.toHaveProperty("args");
    expect(within(card).getAllByTestId("approval-plan-step").map((li) => li.textContent)).toEqual(GOALS);
    expect(within(card).queryByRole("button", { name: "Allow for this chat" })).toBeNull();
    expect(within(card).queryByTestId("approval-local-only")).toBeNull();
    fireEvent.click(within(card).getByRole("button", { name: "Deny" }));
    await waitFor(() =>
      expect(H.api.posts).toContainEqual({ path: `/chat/approvals/${ASK_ID}`, body: { decision: "deny" } }),
    );
  }, 20_000);

  it("the daemon's once_only flag is honoured on any session ask, live or from the listing", async () => {
    openWaitingChat();
    H.ev.list = [
      frame({
        type: "approval.requested",
        session_id: "s1",
        payload: { approval_id: "ask-live", tool: "web_fetch", args: { url: "https://example.com" }, timeout_s: 0, once_only: true },
      }),
    ];
    H.api.getResponses[PENDING] = {
      approvals: [{ id: "ask-polled", tool: "web_search", session_id: "s1", timeout_s: 0, once_only: true }],
    };
    render(<ChatPage />);
    const live = await screen.findByTestId("chat-approval-card", {}, { timeout: 10_000 });
    expect(live.getAttribute("aria-label")).toBe("Approve web_fetch?");
    expect(within(live).queryByRole("button", { name: "Allow for this chat" })).toBeNull();
    // The polled ask is next in the dock: answer the first to bring it up.
    await waitFor(() => expect(screen.getByTestId("dock-ask-count").textContent).toBe("1 of 2"));
    fireEvent.click(within(live).getByRole("button", { name: "Deny" }));
    await land({ type: "approval.resolved", session_id: "s1", payload: { approval_id: "ask-live", decision: "deny" } });
    await waitFor(() => expect(screen.getByTestId("chat-approval-card").getAttribute("aria-label")).toBe("Approve web_search?"));
    const polled = screen.getByTestId("chat-approval-card");
    expect(within(polled).queryByRole("button", { name: "Allow for this chat" })).toBeNull();
  }, 20_000);

  it("anti-vacuity: any other ask of the same run still offers the conversation answer", async () => {
    openWaitingChat();
    H.ev.list = [
      frame({
        type: "approval.requested",
        session_id: "s1",
        payload: { approval_id: "ask-shell", tool: "shell", args: { command: "dir" }, timeout_s: 0 },
      }),
    ];
    render(<ChatPage />);
    const card = await screen.findByTestId("chat-approval-card", {}, { timeout: 10_000 });
    expect(await within(card).findByRole("button", { name: "Allow for this chat" })).toBeTruthy();
    expect(within(card).queryByTestId("approval-plan")).toBeNull();
  }, 20_000);
});
